// nodePriority_ is DiGraphNode::getPriority for the data-flow node comparators. The node is a
// LinkedDiGraphNode, the only DiGraphNode class, so getPriority is called on it directly, and
// the comparator has the function itself, not an adapter object that casts each node to the
// DiGraphNode interface (post-flip manual step).
func nodePriority_(p0 any) int32 {
	return to_LinkedDirectedGraph_LinkedDiGraphNode[Node, ControlFlowGraph_Branch](p0).getPriority()
}

func (this *ControlFlowAnalysis_AstControlFlowGraph) getOptionalNodeComparator_impl(isForward bool) ComparatorOf[DiGraph_DiGraphNode[Node, ControlFlowGraph_Branch]] {
	return func() Comparator {
		if isForward {
			return Comparator_comparingInt_f(nodePriority_)
		}
		return Comparator_reversed(Comparator_comparingInt_f(nodePriority_))
	}()
}
